R = RT.R; lit = G.lit
def _pv_newest():
    fw = X.FW; vk = lambda q: [int(x) for x in re.findall(r"_v(\d+)_(\d+)_(\d+)\.", q)[0]]
    spec = importlib.util.spec_from_file_location("pv", sorted(glob.glob(fw + "/03-tooling/backlog_pipeline_verify_v*.py"), key=vk)[-1])
    m = importlib.util.module_from_spec(spec); spec.loader.exec_module(m)
    m.STAGE_TYPES = m._load_stage_types(sorted(glob.glob(fw + "/01-ontologies/backlog_tbox_v*.ttl"), key=vk)[-1], table="v4")
    return m
X._pv = _pv_newest

REV = "ex:Revision_Lineage3_Backlog10"; OLD = "ex:Out3_BacklogR37"; NEWB = "ex:Out3_BacklogR38"; R.NEWB = NEWB; ITER = "Iter_54"
CRS = ["ex:CR3_ReaderGap", "ex:CR3_PaperFormCode"]; IAS = ["ex:IA3_ReaderGap", "ex:IA3_PaperFormCode"]
WHEN = "Friday 2026-10-30, on the report of the grading executor (commit a575006) and the lineage agent's own reproduction, and the control of the midterm paper"
F_GAP = ("MEASURED 2026-10-30 by the lineage agent with 08-tooling/exam/sen0401_exam_reader_gap_control_v1_0_0.py (logs verify/iter54/ctl/ctl_reader_gap_v1_1_0_reproduction.log): the COMMITTED reader v1.1.0 alone, on sheets of the midterm paper's CHAPTER-ORDER layout, lets a skipped-row shift cross a gap unflagged: seeds 41000-41039: 17 rows (7 of 40 sheets); seeds 52000-52199: 91 rows on 28 of 200 sheets; the grouped-by-type layout: 0 on both. The grading tool v1.0.0 adds two screens that hold the blocks across the gap (0 misses on 63000-63099 and 41000 in my own control), so a grade is protected, but the reader itself is not repaired. The earlier controls of the reader repair and of the paper (small sample, other layout) are corrected by an appended note (v0.722.0).")
F_FORM = ("MEASURED 2026-10-30 by the lineage agent: both orders of the midterm paper print the same form code 10100 on the answer sheet, so a scanned sheet carries nothing that tells which order's key it belongs to (the pair check refuses a key with the other order's layout, but a scanned sheet is graded against the key the instructor chooses). And on item 21 of the grouped order the 45-character line of the listing touches the right border of its code box (read on the rendered page; the executor's checks count characters, not the box). The owner has the grouped-order draft and decides the order and the cs_encode definition: the repair is built together with his changes to the items, as new files (a new items version and a renderer v1.3, never an edit).")
FACT = F_GAP + " " + F_FORM
TXT_RD = ("Make the NEW answer sheet reader v1.2.0 (08-tooling/exam, new files; v1.0.0 and v1.1.0 are never edited, SHA-256 before and after) that holds the rows after a skipped-row shift across a gap on ANY layout, including the midterm paper's chapter-order layout, with the screens of the grading tool v1.0.0 as the starting point (read sen0401_exam_grading_v1_0_0.py extend_holds; it is not edited) built into the reader so that the reader ALONE gives no missed shift row. MEASURE with the control's script sen0401_exam_reader_gap_control_v1_0_0.py (adapt it as a new file to read the new reader): seed blocks 41000-41039, 52000-52199, 62000-62099 and one block you name before the run, on both midterm layouts and on the reader's default layout: 0 missed, 0 silent wrong, 0 empty-not-flagged; the held share at most 25 percent on every layout (v1.1.0 gave 5.7 percent on the chapter layout and 16.3 percent on the grouped layout in 40 sheets); the registration failures 0; the v1.1.0 measurement of the default layout (its own script) not worse. A failing result is never worked around: no threshold is changed to pass without being stated and measured on a block named before the run. DO NOT EDIT OR APPEND TO ANY FILE COMMITTED EARLIER, INCLUDING YOUR OWN LOG FILES. Commit ONLY your own files to main (git add by path, pull --rebase before push); commit each verified step at once. Report every result as printed. Planned session SEN0401-I54-readergap; about 3.0 hours (an estimate, G120).")
TXT_FC = ("Make the NEW midterm paper files for the owner's decisions of the draft (the grouped-order draft was sent to the owner on 2026-10-30; his order, his decision on the cs_encode definition and his changes to the items are inputs): (1) a distinct form code per order (the code is printed on the sheet and read by the reader; the key and the layout carry it and the grading tool's pair check refuses a mismatch; the codes are chosen by a stated rule and are valid for the sheet's check digit if it has one); (2) the code box wide enough for the longest allowed line (45 characters) at the printed type size, in a NEW renderer version (v1.3), with the code boxes of every item tested by measuring the text width against the box; (3) a new items version if the owner changes an item (never an edit of v1.0.0). Rebuild the paper in the owner's order with the new files; the measurement per order, the page counts, the print safety and the key against the items by the control's own script sen0401_exam_papers_control_check_v1_0_0.py. DO NOT EDIT OR APPEND TO ANY FILE COMMITTED EARLIER. STOP and report if a rule would have to change. Report every result as printed. The task waits for the owner's decisions; the lineage agent records them before the start. Planned session SEN0401-I54-paperfix; about 2.0 hours (an estimate, G120).")
VT_RD = "Compare the SHA-256 of the v1.0.0 and v1.1.0 files; run the gap control script on the new reader with new seed blocks of my own on both layouts; run the reader's own measurement; the grading tool on the new reader; nochange."
VT_FC = "Run the papers control script on the rebuilt paper; read every page; measure the code box widths; compare the form codes of the orders and the sheets read with the grading tool pair check; nochange."
def crit_rep():
    base = "Owner-directed repair work (" + ", ".join(CRS) + ", " + WHEN + "). "
    return {"AC3E_Repair_ReaderGap": ("The answer sheet reader v1.2.0 alone gives no missed shift row on any layout",
              base + "Given the reader v1.1.0 (unchanged) when the NEW reader v1.2.0 is made, then ALL of: (1) every file is new and no committed file is edited; (2) the reader ALONE on the midterm chapter-order layout, the grouped layout and the default layout gives 0 missed, 0 silent wrong and 0 empty-not-flagged on the seed blocks 41000-41039, 52000-52199, 62000-62099 and a block named before the run; (3) the held share is at most 25 percent on every layout and every sheet registers; (4) the v1.1.0 measurement on the default layout is not worse. Results as printed; if any element fails the work is named failing. " + FACT, "own gap control script; reader measurement; grading tool"),
            "AC3E_Repair_PaperFormCode": ("The midterm paper has a distinct form code per order and a code box wide enough for its longest line",
              base + "Given the midterm paper files of v1.0.0 (unchanged) and the owner's decisions on the draft when the NEW paper files are made, then ALL of: (1) every file is new and no committed file is edited; (2) the two orders print different form codes and the key, layout and sheet of an order carry its own; (3) no line of a code box is wider than its box, measured for every item; (4) the paper is built in the owner's order, with a new items version for his changes, and the papers control script passes (key against the items, pages, print safety, reader on the sheet layout). Results as printed; if any element fails the work is named failing. " + FACT, "papers control script; own width measurement")}
STS = [("ST_Repair_Exam_Reader", "REPAIR: the answer sheet reader v1.2.0 holds shifted rows across a gap on every layout", ["AC3E_Repair_ReaderGap"], ["TK_Repair_Exam_Reader_Build", "TK_Repair_Exam_Reader_Verify"], "SEN0401-I54-readergap", TXT_RD, VT_RD, 3.0, [], 1.0, "Del3_ExamPapers", "Obj3_Exam"),
       ("ST_Repair_Exam_Paper", "REPAIR: the midterm paper with a distinct form code per order and a wide enough code box, with the owner's changes", ["AC3E_Repair_PaperFormCode"], ["TK_Repair_Exam_Paper_Build", "TK_Repair_Exam_Paper_Verify"], "SEN0401-I54-paperfix", TXT_FC, VT_FC, 2.0, [], 1.0, "Del3_ExamPapers", "Obj3_Exam")]
def ev_change(t):
    cr1 = ('\n%s a backlog:ChangeRequest ;\n    rdfs:label "The reader v1.1.0 misses skipped-row shifts on the chapter-order layout"@en ;\n    backlog:requestsChangeTo ex:Scope3 ; backlog:hasChangeDirection backlog:Direction_Grow ; backlog:hasDisposition backlog:Disp_Pending ; rdfs:seeAlso %s, ex:CR3_ExamMission ;\n    backlog:hasChangeRequestRationale %s .\n') % (CRS[0], IAS[0], lit("Raised " + WHEN + ". " + F_GAP))
    cr2 = ('\n%s a backlog:ChangeRequest ;\n    rdfs:label "The two orders of the midterm paper print one form code, and a code box is too narrow for its longest line"@en ;\n    backlog:requestsChangeTo ex:Scope3 ; backlog:hasChangeDirection backlog:Direction_Grow ; backlog:hasDisposition backlog:Disp_Pending ; rdfs:seeAlso %s, ex:CR3_ExamMission ;\n    backlog:hasChangeRequestRationale %s .\n') % (CRS[1], IAS[1], lit("Raised " + WHEN + ". " + F_FORM))
    ia1 = ('\n%s a backlog:ImpactAssessment ;\n    rdfs:label "What the reader gap costs and touches"@en ;\n    backlog:analyzesRequest %s ; backlog:identifiesAffectedLineage ex:Lineage3 ;\n    backlog:hasImpactStatement %s .\n') % (IAS[0], CRS[0], lit(F_GAP + " AFFECTED: one new repair story (the reader v1.2.0, new files); the grading story is Done and protected by its screens; the choice of the order of the paper (the grouped order gave no gap). NOT AFFECTED: every committed file. ORDER: the exams come first; the repair is ranked by the rank tool. ESTIMATE (G120): 3 h build, 1 h verification."))
    ia2 = ('\n%s a backlog:ImpactAssessment ;\n    rdfs:label "What the form code and the code box cost and touch"@en ;\n    backlog:analyzesRequest %s ; backlog:identifiesAffectedLineage ex:Lineage3 ;\n    backlog:hasImpactStatement %s .\n') % (IAS[1], CRS[1], lit(F_FORM + " AFFECTED: one new repair story (new paper files, renderer v1.3, an items version if the owner changes an item). NOT AFFECTED: every committed file, the reader. ESTIMATE (G120): 2 h build, 1 h verification."))
    return t + cr1 + cr2 + ia1 + ia2, "Two change requests with impact assessments: the reader v1.1.0 misses skipped-row shifts on the chapter-order layout (reproduced), and the paper's one form code for two orders and a code box too narrow for a 45-character line; no stage changed."
def ev_retract(t):
    reason = ("The change requests " + ", ".join(CRS) + " (" + WHEN + ") add two stories with their own criteria; a new criterion is counted by the Backlog digest, so the Backlog stage is revised (G125 route 2): this version retracts the Backlog output " + OLD + " and rebuilds nothing; the next version rebuilds it and a third fills the last commit; the items already in it are re-admitted by the rebuilt output.")
    b = ('\n%s a backlog:StageRevision ;\n    rdfs:label "Revision of the third lineage from the Backlog stage: two exam repairs"@en ;\n    backlog:revisesLineage ex:Lineage3 ; backlog:revisesFromStage backlog:Stage_Backlog ;\n'
         '    rdfs:seeAlso %s, %s ;\n    backlog:revisionReason %s ;\n    backlog:retractsOutput %s ; backlog:decidedBy backlog:Builder ;\n    backlog:revisedAtCommit "PENDING" .\n%s backlog:outputRetracted true .\n') % (REV, ", ".join(CRS), ", ".join(IAS), lit(reason), OLD, OLD)
    return X.set_status(t, "LS_Objectived") + b, "StageRevision of the third lineage from the Backlog stage (G125 route 2): the Backlog output %s is retracted for the two exam repairs; nothing is rebuilt here." % OLD.replace("ex:", "")
def ev_backlog(t, prev):
    t = re.sub(r'(%s a backlog:StageRevision.*?backlog:revisedAtCommit )"PENDING"' % re.escape(REV), lambda m: m.group(1) + '"%s"' % prev, t, count=1, flags=re.S)
    t = X.set_status(t, "LS_Backlogged"); now = M.now()
    n = t.count("backlog:admittedByOutput %s ;" % OLD); assert n >= 40, n
    t = t.replace("backlog:admittedByOutput %s ;" % OLD, "backlog:admittedByOutput %s ;" % NEWB)
    L = []; note = "Admitted " + WHEN + " (" + ", ".join(CRS) + "). One criterion per unit (G133). Done stories and tasks stay Done and are not edited (G125)."
    for aid, (label, g_, tl, ver) in crit_rep().items():
        k = aid[4:]
        L.append(RT.ac_block(aid, label, g_, tl, ver, k).replace("ex:TC9_", "ex:TC9R_"))
        L.append(RT.case_blocks(k, aid).replace("Spec3I_Retro24", "Spec3I_Ch06Teach").replace("ex:Data3S_TC9_", "ex:Data3S_TC9R_").replace("ex:TC9_", "ex:TC9R_")
            .replace("Run the checks on the item as measured in the baseline of 2026-10-25 (an overlap, a manifest example that starts with an error name, a story whose text lies below the first screen, a committed file with status M) and require that nothing is claimed for it.", "Run the checks on the item as it stands before the work and require that nothing is claimed for it.")
            .replace("The finding as measured in the baseline of 2026-10-25 (ex:IA3_Retro24).", "The finding as measured on 2026-10-30 (ex:IA3_ReaderGap, ex:IA3_PaperFormCode)."))
    mem = []
    for (sid, title, crits_, tks, sess, txt, vtxt, hrs, deps, vh, dl, ob) in STS:
        mem += [sid] + tks
        L.append(R.story_block(sid, title, dl, ob, crits_, tks, note, "ex:" + ITER, "Proposed"))
        L.append(R.task_block(tks[0], "Build: " + title, "Build", deps, sess, "S", hrs, txt, "ex:" + ITER, "Proposed", True))
        L.append(R.task_block(tks[1], "Verify: " + title, "Verify", [tks[0]], "builder", "S+%.1fh" % hrs, vh, vtxt, "ex:" + ITER, "Proposed", True))
        L.append("ex:%s backlog:standsAlone true .\n" % sid)
    i, j = T.blk(t, ITER); b = t[i:j]; m = re.search(r"backlog:hasMember ([^;.]*?)( ;| \.|\.\n)", b, re.S); assert m
    t = t[:i] + b.replace(m.group(0), "backlog:hasMember " + m.group(1).rstrip() + ", " + ", ".join("ex:" + x for x in mem) + m.group(2), 1) + t[j:]
    L.append("ex:Obj3_Exam backlog:metricMovableBy ex:ST_Repair_Exam_Reader, ex:ST_Repair_Exam_Paper .\n")
    L.append('ex:SC3_ExamRepairs a backlog:ScopeChange ;\n    rdfs:label "Backlog widened by the reader repair and the paper repair"@en ;\n    backlog:fulfillsRequest %s ; backlog:changesScope ex:Scope3 ; backlog:decidedBy backlog:Builder ;\n    backlog:admitsItem %s ;\n    backlog:hasScopeChangeRationale %s .\n' % (", ".join(CRS), ", ".join("ex:" + s[0] for s in STS), lit("Required by the defects found in the delivered exam work and reproduced by the lineage agent; the rule that a repair enters the backlog and re-ranks the open items. " + FACT)))
    for c in CRS:
        t, kk = re.subn(r'(%s a backlog:ChangeRequest ;.*?backlog:hasDisposition )backlog:Disp_Pending' % re.escape(c), lambda m: m.group(1) + "backlog:Disp_Accepted", t, count=1, flags=re.S); assert kk == 1, c
        L.append('%s rdfs:comment "Disposition set to Accepted on %s in the version that records the ScopeChange ex:SC3_ExamRepairs; it was Pending before."@en .\n' % (c, now[:10]))
    t += "\n" + "".join(L)
    return t + ('\nex:Out3_BacklogR38 a backlog:StageOutput ;\n    rdfs:label "Closure of the Backlog stage of the third lineage, rebuilt for the two exam repairs"@en ;\n    backlog:belongsToLineage ex:Lineage3 ;\n'
                '    backlog:outputOfStage backlog:Stage_Backlog ;\n    backlog:consumesOutput ex:Out3_ObjectiveR32 ;\n    backlog:hasStateDigest "%s" ;\n    backlog:closedAtCommit "PENDING" .\n') % X.digest(t, "Backlog"), \
        "third lineage, Backlog stage rebuilt: two exam repair stories (the reader v1.2.0, the paper form code and code box with the owner's changes), both change requests Accepted; %d items re-admitted." % n
def ev_fill(t, prev): return G.fill_re(t, NEWB, prev), "closedAtCommit of the rebuilt Backlog output %s set to the commit that closed it (%s)." % (NEWB.replace("ex:", ""), prev)
def main():
    ev = sys.argv[1]; src = M.newest(); t = open(src, encoding="utf-8").read(); nxt, cur = M.next_version(src)
    fn = {"change": lambda: ev_change(t), "retract": lambda: ev_retract(t), "backlog": lambda: ev_backlog(t, sys.argv[2]), "fill": lambda: ev_fill(t, sys.argv[2])}
    nt, comment = fn[ev](); print(os.path.basename(M.write_new(src, nt, nxt, cur, comment)))
if __name__ == "__main__": main()
